import{_ as l,c as a,o as i,a4 as e}from"./chunks/framework.CpVK_f0P.js";const f=JSON.parse('{"title":"每日训练流程","description":"","frontmatter":{},"headers":[],"relativePath":"method/daily-workflow.md","filePath":"method/daily-workflow.md"}'),n={name:"method/daily-workflow.md"},r=e(`<h1 id="每日训练流程" tabindex="-1">每日训练流程 <a class="header-anchor" href="#每日训练流程" aria-label="Permalink to &quot;每日训练流程&quot;">​</a></h1><h2 id="当前阶段的材料" tabindex="-1">当前阶段的材料 <a class="header-anchor" href="#当前阶段的材料" aria-label="Permalink to &quot;当前阶段的材料&quot;">​</a></h2><ul><li>主线：《走遍美国》，按 Act 做精听、复述、纠错和再次复述</li><li>补充：<a href="https://learnenglish.britishcouncil.org/free-resources/listening/a2" target="_blank" rel="noreferrer">British Council A2 Listening</a> 的成人日常和工作场景</li><li>选用：<a href="https://www.bbc.co.uk/learningenglish/english/features/6-minute-english" target="_blank" rel="noreferrer">BBC 6 Minute English</a> 中感兴趣的成人主题</li><li>输出：站会汇报、Bug 描述、技术讨论和需求确认</li></ul><p>每天优先完成主线训练。补充材料用于接触不同人物和语速，不能替代脱稿输出。</p><h2 id="核心流程" tabindex="-1">核心流程 <a class="header-anchor" href="#核心流程" aria-label="Permalink to &quot;核心流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>听材料</span></span>
<span class="line"><span>→ 理解内容</span></span>
<span class="line"><span>→ 第一次复述</span></span>
<span class="line"><span>→ 检查错误</span></span>
<span class="line"><span>→ 提炼 3～5 个表达</span></span>
<span class="line"><span>→ 替换造句</span></span>
<span class="line"><span>→ 第二次复述</span></span>
<span class="line"><span>→ 隔天复习</span></span></code></pre></div><h2 id="最低版-20-30-分钟" tabindex="-1">最低版：20～30 分钟 <a class="header-anchor" href="#最低版-20-30-分钟" aria-label="Permalink to &quot;最低版：20～30 分钟&quot;">​</a></h2><h3 id="第一阶段-听和理解-5-8-分钟" tabindex="-1">第一阶段：听和理解（5～8 分钟） <a class="header-anchor" href="#第一阶段-听和理解-5-8-分钟" aria-label="Permalink to &quot;第一阶段：听和理解（5～8 分钟）&quot;">​</a></h3><ol><li>选一段 1～3 分钟的材料（如《走遍美国》某一节）</li><li>先不看文本，听 1～2 遍，抓大意</li><li>遇到听不懂的地方，看文本确认</li><li>确保没有不认识的关键词</li></ol><h3 id="第二阶段-第一次复述-5-分钟" tabindex="-1">第二阶段：第一次复述（5 分钟） <a class="header-anchor" href="#第二阶段-第一次复述-5-分钟" aria-label="Permalink to &quot;第二阶段：第一次复述（5 分钟）&quot;">​</a></h3><ol><li>关掉材料，用自己的话复述刚才听到的内容</li><li>可以录音，方便回听</li><li>不追求完美，先说出来</li></ol><h3 id="第三阶段-检查和提炼-5-8-分钟" tabindex="-1">第三阶段：检查和提炼（5～8 分钟） <a class="header-anchor" href="#第三阶段-检查和提炼-5-8-分钟" aria-label="Permalink to &quot;第三阶段：检查和提炼（5～8 分钟）&quot;">​</a></h3><ol><li>回听录音或回忆复述过程，找出问题： <ul><li>哪里卡住了？</li><li>哪里用了中文思维？</li><li>哪里时态搞错了？</li><li>哪个词不确定？</li></ul></li><li>从材料中提炼 3～5 个值得练习的表达</li><li>每个表达用自己的场景造 2～3 个替换句</li></ol><h3 id="第四阶段-第二次复述-5-分钟" tabindex="-1">第四阶段：第二次复述（5 分钟） <a class="header-anchor" href="#第四阶段-第二次复述-5-分钟" aria-label="Permalink to &quot;第四阶段：第二次复述（5 分钟）&quot;">​</a></h3><ol><li>重新复述同一段内容</li><li>尝试主动使用刚刚提炼的表达</li><li>对比两次复述的差异</li></ol><h3 id="隔天复习" tabindex="-1">隔天复习 <a class="header-anchor" href="#隔天复习" aria-label="Permalink to &quot;隔天复习&quot;">​</a></h3><ul><li>第二天花 3～5 分钟重新复述同一段内容</li><li>检查重点表达是否还能主动使用</li><li>一周后再复述一次，确认掌握程度</li></ul><h2 id="完整版-60-90-分钟" tabindex="-1">完整版：60～90 分钟 <a class="header-anchor" href="#完整版-60-90-分钟" aria-label="Permalink to &quot;完整版：60～90 分钟&quot;">​</a></h2><p>时间充足时，在最低版之外增加以下内容：</p><ul><li>跟读 10～15 分钟：模仿当前材料的重音、停顿和连读</li><li>成人短听力 10～15 分钟：从 British Council A2 Listening 或 BBC 6 Minute English 选一段，结束后用 3～5 句英语复述</li><li>工作场景 15～20 分钟：写关键词，脱稿表达，检查问题，再说一遍</li><li>词汇维护 5～10 分钟（可选）：只复习已有内容，不设每日新词数量</li></ul><p>完整版不是每天必须完成的硬指标。忙时只做最低版，避免因为时间不足而完全中断。</p><h2 id="工作场景轮换" tabindex="-1">工作场景轮换 <a class="header-anchor" href="#工作场景轮换" aria-label="Permalink to &quot;工作场景轮换&quot;">​</a></h2><p>如果时间允许，可以在上述训练之外加入工作场景练习：</p><ul><li>周一/四：Stand-up 站会汇报</li><li>周二/五：描述 Bug / 技术问题</li><li>周三/六：技术讨论 / 确认需求</li><li>周日：自由复习或休息</li></ul><p>每个场景的训练方式：写下内容 → 脱稿说出来 → 录音 → 回听纠正 → 再录一遍。</p><h2 id="材料切换计划" tabindex="-1">材料切换计划 <a class="header-anchor" href="#材料切换计划" aria-label="Permalink to &quot;材料切换计划&quot;">​</a></h2><ul><li>第 1～2 个月：以《走遍美国》为主，搭配 British Council A2 Listening 的成人日常和工作场景；BBC 6 Minute English 只作为补充</li><li>第 3～4 个月：Friends / Modern Family 只用于泛听；精听逐步换成英文 技术视频、会议 talk 和 Business English Pod</li><li>第 5 个月起：真实会议、技术视频和 TED 成为主线，影视只作为补充</li></ul><p>精听材料必须带文本或字幕，主题要对成人生活或工作有用，连续语言要占主要部分； 跟读材料要发音清晰、语速适中。儿童主题、无意义声音或音效过多的材料直接淘汰。 是否换阶段由实际训练表现决定，不机械地按日期切换。</p><h2 id="听力级别升级标准" tabindex="-1">听力级别升级标准 <a class="header-anchor" href="#听力级别升级标准" aria-label="Permalink to &quot;听力级别升级标准&quot;">​</a></h2><p>当前 A2 新材料第一遍约能理解 50%，A2 继续作为主训练级别。B1 可以每周试听 一段，用于观察变化，但暂时不替代 A2。</p><p>听懂率按主要信息估算，不按听出的单词数量计算：能否说出主题、人物目的、 关键事实和最后结果。</p><ul><li><a href="https://learnenglish.britishcouncil.org/free-resources/listening/a2" target="_blank" rel="noreferrer">A2 Listening</a>： 短而清楚的日常和工作对话</li><li><a href="https://learnenglish.britishcouncil.org/free-resources/listening/b1" target="_blank" rel="noreferrer">B1 Listening</a>： 电话、会议、采访以及清晰的日常或工作话题</li><li><a href="https://learnenglish.britishcouncil.org/free-resources/listening/b2" target="_blank" rel="noreferrer">B2 Listening</a>： 更长的广播、访谈、演讲和包含复杂观点的熟悉话题</li></ul><p>同一级别连续 5 段从未听过的材料达到以下标准，再把下一级别加入主训练：</p><ol><li>第一遍不看文本能理解约 70% 的主要信息。</li><li>第二遍不看文本能理解约 80%。</li><li>配套理解题正确率达到 80%。</li><li>不看文本能用 3～5 句英语复述主题、关键事件和结果。</li></ol><p>第一次只能听懂 40%～60% 的材料适合精听；低于 40% 时只作偶尔尝试；稳定达到 70% 以上时开始加入下一级别。升级后的前两周按当前级别 70%、下一级别 30% 分配，不一次性全部替换。</p><h2 id="每四周固定测试" tabindex="-1">每四周固定测试 <a class="header-anchor" href="#每四周固定测试" aria-label="Permalink to &quot;每四周固定测试&quot;">​</a></h2><p>测试条件保持一致，才能纵向比较：</p><ul><li>2 分钟自我介绍 + 3 分钟 stand-up + 5 分钟项目介绍</li><li>听一段没听过的 2 分钟材料两遍，然后脱稿复述</li><li>与 AI 或真人进行 10 分钟连续工作场景对话</li><li>用 10 分钟写一封进度汇报或 Bug 描述</li></ul><p>重点观察：沉默卡顿是否减少、能否说完整句、是否依赖中译英，以及能否听懂并 回答追问。四到八周没有变化时，调整材料难度或输出量。</p>`,39),s=[r];function t(o,h,p,c,u,d){return i(),a("div",null,s)}const g=l(n,[["render",t]]);export{f as __pageData,g as default};
